public int minEatingSpeed(int[] piles, int h) {
    int max = 0;
    for (int p : piles) max = Math.max(max, p);
    for (int k = 1; k <= max; k++) {
        long hours = 0;
        for (int p : piles) {
            hours += (p + k - 1) / k;   // ceil(p / k)
        }
        if (hours <= h) {
            return k;
        }
    }
    return max;
}

